import{currentUserRole}from"@/lib/role";import{redirect}from"next/navigation";import Link from"next/link";export default async function History(){const{user,role,s}=await currentUserRole();if(!user)redirect("/auth");if(role!=="vendor")redirect(role==="admin"?"/admin":"/");const{data:o}=await s.from("orders").select("*").eq("vendor_user_id",user.id).eq("status","delivered").order("created_at",{ascending:false});return <main className="shell"><h1>Order history</h1>{o?.length?o.map(x=><section className="card" key={x.id}><b>{x.order_code}</b><p>{x.quantity_kg} kg · Delivered</p></section>):<section className="card">No completed orders yet.</section>}<Link className="btn" href="/vendor">Back to dashboard</Link></main>}